// Normalizes Apify output for one competitor and builds the Claude request.
const s = $('Settings').first().json;
const comp = $('Loop Over Competitors').first().json;
const competitor = String(comp.name || comp.linkedin_url || '').trim();

// Apify actors name fields differently; take the first non-empty match.
const pick = (obj, ...paths) => {
  for (const path of paths) {
    let cur = obj;
    for (const key of path.split('.')) { cur = cur == null ? undefined : cur[key]; }
    if (cur !== undefined && cur !== null && cur !== '') return cur;
  }
  return undefined;
};
const num = v => { const n = parseInt(String(v ?? 0).replace(/,/g, ''), 10); return isNaN(n) ? 0 : n; };
const cutoff = Date.now() - Number(s.days) * 86400000;

const posts = $input.all().map(i => i.json)
  .map(it => {
    let postedAt = pick(it, 'postedAt.date', 'postedAt', 'posted_at.date', 'posted_at', 'date', 'publishedAt') ?? '';
    if (typeof postedAt === 'object') postedAt = postedAt.date || postedAt.timestamp || '';
    const likes = num(pick(it, 'engagement.likes', 'stats.total_reactions', 'numLikes', 'likes', 'reactionsCount'));
    const comments = num(pick(it, 'engagement.comments', 'stats.comments', 'numComments', 'comments', 'commentsCount'));
    const shares = num(pick(it, 'engagement.shares', 'stats.reposts', 'numShares', 'shares', 'repostsCount'));
    return {
      text: String(pick(it, 'content', 'text', 'postText', 'commentary') ?? ''),
      post_url: String(pick(it, 'linkedinUrl', 'postUrl', 'url', 'post_url', 'shareUrl') ?? ''),
      posted_at: String(postedAt),
      likes, comments, shares,
      // Comments and reshares signal more intent than a like.
      engagement_score: likes + 2 * comments + 3 * shares,
    };
  })
  .filter(p => p.text && p.post_url)
  .filter(p => { const t = Date.parse(p.posted_at); return isNaN(t) || t >= cutoff; })
  .slice(0, Number(s.maxPosts))
  .sort((a, b) => b.engagement_score - a.engagement_score);

if (!posts.length) return [{ json: { skip: true, competitor } }];

const system = `You are a LinkedIn content strategist doing competitive research.
You will get one competitor's recent posts with engagement numbers. For each post,
identify its format, topic, opening hook (quote the first line), hook type (e.g.
contrarian take, personal story, number/list, question, bold claim), call to action
(or "none"), and in one or two sentences why it performed the way it did relative
to the competitor's other posts.

Then summarize the competitor's overall strategy, the themes that drive the most
engagement, concrete tactics worth borrowing, and specific post ideas the reader
could write. Tailor the ideas to the reader's niche when one is given. Base
everything on the posts provided; do not invent metrics.`;

const str = { type: 'string' };
const list = { type: 'array', items: str };
const schema = {
  type: 'object', additionalProperties: false,
  required: ['posts', 'summary', 'top_themes', 'what_to_steal', 'content_ideas'],
  properties: {
    posts: { type: 'array', items: {
      type: 'object', additionalProperties: false,
      required: ['post_index', 'format', 'topic', 'hook', 'hook_type', 'cta', 'why_it_worked'],
      properties: {
        post_index: { type: 'integer' },
        format: { type: 'string', enum: ['text', 'image', 'carousel', 'video', 'poll', 'article', 'other'] },
        topic: str, hook: str, hook_type: str, cta: str, why_it_worked: str,
      } } },
    summary: str, top_themes: list, what_to_steal: list, content_ideas: list,
  },
};

const postsBlock = posts.map((p, i) =>
  `<post index="${i}" likes="${p.likes}" comments="${p.comments}" shares="${p.shares}" posted_at="${p.posted_at}">\n${p.text}\n</post>`
).join('\n\n');

return [{ json: {
  skip: false, competitor, posts,
  requestBody: {
    model: s.model,
    max_tokens: 16000,
    system,
    messages: [{ role: 'user', content:
      `Competitor: ${competitor}\nMy niche: ${s.niche || 'not specified'}\n\n${postsBlock}\n\n` +
      `Analyze every post (indexes 0 to ${posts.length - 1}).` }],
    output_config: { effort: 'medium', format: { type: 'json_schema', schema } },
    // If a safety classifier declines, the API retries on a recommended fallback model.
    fallbacks: 'default',
  },
} }];

// Turns Claude's JSON report into one row per post for the Posts tab.
const res = $input.first().json;
const prep = $('Prepare Posts').first().json;
if (res.stop_reason === 'refusal') throw new Error(`Claude declined to analyze ${prep.competitor}`);
if (res.stop_reason === 'max_tokens') throw new Error(`Analysis for ${prep.competitor} was cut off; lower maxPosts in Settings`);

const report = JSON.parse(res.content.filter(b => b.type === 'text').map(b => b.text).join(''));
const byIndex = Object.fromEntries(report.posts.map(a => [a.post_index, a]));
const runAt = $now.toFormat('yyyy-MM-dd HH:mm');

return prep.posts.map((p, i) => {
  const a = byIndex[i] || {};
  return { json: {
    scraped_at: runAt,
    competitor: prep.competitor,
    posted_at: p.posted_at,
    post_url: p.post_url,
    likes: p.likes,
    comments: p.comments,
    shares: p.shares,
    engagement_score: p.engagement_score,
    format: a.format || '',
    topic: a.topic || '',
    hook: a.hook || '',
    hook_type: a.hook_type || '',
    cta: a.cta || '',
    why_it_worked: a.why_it_worked || '',
    post_text: p.text.slice(0, 45000), // Sheets caps a cell at 50k characters
  } };
});

// One summary row per competitor for the Insights tab.
const res = $('Claude Analyze').first().json;
const prep = $('Prepare Posts').first().json;
const report = JSON.parse(res.content.filter(b => b.type === 'text').map(b => b.text).join(''));
const bullets = items => items.map(x => `• ${x}`).join('\n');

return [{ json: {
  run_at: $now.toFormat('yyyy-MM-dd HH:mm'),
  competitor: prep.competitor,
  posts_analyzed: prep.posts.length,
  summary: report.summary,
  top_themes: bullets(report.top_themes),
  what_to_steal: bullets(report.what_to_steal),
  content_ideas: bullets(report.content_ideas),
} }];
